import { describe, it, expect } from "vitest";
import { iOfT } from "./iOfT";

describe("iOfT", () => {
  it("matches Python reference (formulas_v3speed.I_of_T) at canonical T values", () => {
    // Generated by running the Python reference at the values below.
    const cases: Array<[number, number]> = [
      [1, 13.5970804254815807],
      [10, 692.197264351314857],
      [50, 16023.1697171709111],
      [100, 63461.2187966089041],
      [500, 1573938.96664589667],
      [1000, 6289469.53968497366],
    ];
    for (const [t, expected] of cases) {
      const got = iOfT(t);
      const rel = Math.abs(got - expected) / Math.abs(expected);
      expect(rel).toBeLessThan(1e-12);
    }
  });

  it("throws for non-positive T", () => {
    expect(() => iOfT(0)).toThrow();
    expect(() => iOfT(-1)).toThrow();
  });

  it("is monotonically increasing on T > 0", () => {
    let prev = -Infinity;
    for (let t = 0.5; t < 100; t += 0.5) {
      const v = iOfT(t);
      expect(v).toBeGreaterThan(prev);
      prev = v;
    }
  });
});
